css:
/* Global Styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    min-height: 100vh;
}

/* Container */
.container {
    max-width: 100%;
    margin: 0 auto;
    padding: 30px;
}

/* Logo and Title */
.logo-container {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 10px 20px;
}

.logo {
    max-width: 80px;
    height: auto;
}

/* Header */
.header {
    display: flex;
    justify-content: space-between;
    margin-bottom: 30px;
}

.header .details {
    font-size: 16px;
    line-height: 1.8;
}

/* Title */
.title {
    text-align: center;
    margin-bottom: 30px;
    margin-top: -30px;
}

/* Table */
.table {
    max-width: 100%;
    margin: 0 auto;
    border-collapse: collapse;
    margin-top: 30px;
    font-size: 16px;
}

.table-bordered th, .table-bordered td {
    border: 1px solid #000;
    padding: 8px;
    text-align: left;
}

.table-bordered th {
    background-color: #2b2a28;
    text-align: center;
    color: white;
}

/* Alternating Row Colors */
.table-bordered tbody tr:nth-child(even) {
    background-color: #f2f2f2;
}

/* Responsive Design */
@media (max-width: 768px) {
    .header {
        flex-direction: column;
        text-align: center;
    }

    .table {
        width: 100%;
    }
}
